functionProofs.body:
BEGIN
 IF NEW."subjectKind" = 'public_cash' OR NEW."impactKind" = 'public_cash_funds_decrease' THEN
   IF NOT coalesce(NEW."subjectRole" = 'actual_payer' AND NEW."subjectKind" = 'public_cash'
       AND NEW."sourceType" = 'payment_execution'
       AND public."jg_registered_payment_impact_matches"(NEW."sourceBusinessId",NEW."projectId",NEW."amountCents",NEW."subjectKind",NEW."subjectId",NEW."impactKind",NEW."sourceImpactKey",NEW."direction",NEW."idempotencyKey"),FALSE) THEN
     RAISE EXCEPTION 'public cash impact must be the exact canonical registered source posting';
   END IF;
 END IF;
 RETURN NEW;
END

BEGIN
 IF NEW."sourceType" = 'payment_execution' AND EXISTS (
   SELECT 1 FROM public."RegisteredPaymentFunding" funding WHERE funding."executionId" = NEW."sourceBusinessId"
 ) THEN
   -- Permanent graph proof only: never re-run current actor/round/history/date
   -- or the initial account CAS when a later projection is appended.
   PERFORM public."jg_assert_registered_payment_intercompany_complete"(NEW."sourceBusinessId");
 END IF;
 RETURN NULL;
END

BEGIN
 RETURN QUERY SELECT p."id",p."operatingLedgerEffectiveDate" FROM public."Project" p WHERE p."id"=project_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'registered payment requires an existing project scope'; END IF;
END

DECLARE covered_id TEXT;
BEGIN
 IF pg_catalog.cardinality(NEW."coveredExecutionIds") <> (SELECT pg_catalog.count(DISTINCT id) FROM pg_catalog.unnest(NEW."coveredExecutionIds") id) THEN
   RAISE EXCEPTION 'covered payment identities must be unique';
 END IF;
 FOREACH covered_id IN ARRAY NEW."coveredExecutionIds" LOOP
   IF NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentFunding" f WHERE f."executionId" = covered_id AND f."accountId" = NEW."accountId") THEN
     RAISE EXCEPTION 'covered payment must be an existing fact of the same account';
   END IF;
 END LOOP;
 RETURN NEW;
END

DECLARE eid TEXT; f public."RegisteredPaymentFunding"; e public."PaymentExecution";
 a public."RegisteredFundAccount"; r public."FundAccountBalanceRegistration"; total NUMERIC; line_count BIGINT;
BEGIN
 eid := NEW."executionId";
 SELECT * INTO STRICT f FROM public."RegisteredPaymentFunding" WHERE "executionId" = eid;
 SELECT * INTO STRICT e FROM public."PaymentExecution" WHERE "id" = eid;
 SELECT * INTO STRICT a FROM public."RegisteredFundAccount" WHERE "id" = f."accountId";
 SELECT * INTO STRICT r FROM public."FundAccountBalanceRegistration" WHERE "id" = f."balanceRegistrationId" AND "accountId" = a."id";
 IF e."amountCents" <= 0 OR r."status" <> 'confirmed' OR
    NOT COALESCE(((a."kind" = 'company' AND f."actualPayerKind" = 'participating_company' AND f."actualPayerId" = a."companyEntityId" AND f."actualPayerSnapshot"->>'companyEntityId' = a."companyEntityId") OR
         (a."kind" = 'public_cash' AND a."companyEntityId" IS NULL AND f."actualPayerKind" = 'public_cash' AND f."actualPayerId" = 'public_cash' AND f."actualPayerSnapshot"->>'scopeKey' = 'public_cash')),FALSE) THEN
   RAISE EXCEPTION 'registered payment requires the frozen canonical account identity';
 END IF;
 SELECT coalesce(pg_catalog.sum(p."amountCents"),0),pg_catalog.count(*) INTO total,line_count FROM public."RegisteredFundPaymentAllocation" p WHERE p."executionId" = eid;
 IF (f."openingTreatment" = 'included' AND line_count <> 0) OR
    (f."openingTreatment" = 'not_included' AND (line_count = 0 OR total <> e."amountCents")) THEN
   RAISE EXCEPTION 'registered payment allocations do not conserve the canonical payment';
 END IF;
 IF EXISTS (SELECT 1 FROM public."RegisteredFundPaymentAllocation" p JOIN public."FundAccountSourceBatch" s ON s."id" = p."sourceBatchId" WHERE p."executionId" = eid AND (p."accountId" <> a."id" OR s."registrationId" <> r."id")) THEN
   RAISE EXCEPTION 'registered payment source belongs to a different frozen reconciliation';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentEvent" event WHERE event."executionId" = eid AND event."eventType" = 'payment_execution.registered' AND event."payload"->>'executionId' = eid AND event."payload"->>'accountId' = a."id" AND event."payload"->>'balanceRegistrationId' = r."id") THEN
   RAISE EXCEPTION 'registered payment requires its same-transaction durable event';
 END IF;
 IF (SELECT pg_catalog.count(*) FROM public."AuditLog" audit WHERE audit."action" = 'payment.execution.record'
       AND audit."businessType" = 'payment_request' AND audit."businessId" = e."paymentRequestId" AND audit."actorUserId" = e."executedByUserId"
       AND audit."metadata"->>'executionId' = e."id" AND audit."metadata"->>'idempotencyKey' = e."idempotencyKey"
       AND pg_catalog.jsonb_typeof(audit."metadata"->'amountCents') = 'string' AND audit."metadata"->>'amountCents' = e."amountCents"::TEXT
       AND audit."metadata"->'voucherFileId' = 'null'::JSONB AND audit."metadata"->'voucherPending' = 'true'::JSONB
       AND audit."metadata"->'actualPayer'->>'kind' = f."actualPayerKind" AND audit."metadata"->'actualPayer'->>'id' = f."actualPayerId"
       AND audit."metadata"->'actualPayer'->'snapshot' = f."actualPayerSnapshot"
       AND audit."metadata"->'payer'->>'paymentSubjectType' = 'our_company'
       AND audit."metadata"->'payer'->>'companyEntityIdSnapshot' = e."companyEntityIdSnapshot"
       AND audit."metadata"->'payer'->>'companyEntityNameSnapshot' = e."companyEntityNameSnapshot"
       AND audit."metadata"->'payer'->>'companyEntityCreditCodeSnapshot' = e."companyEntityCreditCodeSnapshot"
       AND audit."metadata"->>'paidAt' = pg_catalog.to_char(e."paidAt",'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       AND audit."metadata"->'funding'->>'kind' = 'registered_fund_account'
       AND audit."metadata"->'funding'->>'openingTreatment' = f."openingTreatment"
       AND audit."metadata"->'funding'->>'accountId' = a."id" AND audit."metadata"->'funding'->>'balanceRegistrationId' = r."id"
       AND audit."metadata"->>'fromStatus' = (SELECT event."payload"->'writeAuthority'->>'requestStatusBeforeExecution' FROM public."RegisteredPaymentEvent" event WHERE event."executionId" = eid)
       AND audit."metadata"->>'toStatus' = (SELECT request."status" FROM public."PaymentRequest" request WHERE request."id" = e."paymentRequestId")) <> 1 THEN
   RAISE EXCEPTION 'registered payment requires one exact same-transaction canonical audit consequence';
 END IF;
 -- Deferred only, after all same-transaction root/fact/impact inserts.
 PERFORM public."jg_assert_registered_payment_intercompany_complete"(eid);
 RETURN NULL;
END

BEGIN
 IF NEW."voucherFileId" IS NULL AND NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentFunding" WHERE "executionId" = NEW."id") THEN
   RAISE EXCEPTION 'legacy payment requires its original voucher';
 END IF;
 RETURN NULL;
END

DECLARE r public."FundAccountBalanceRegistration"; request_id TEXT; round_status TEXT; project_id TEXT; effective_date DATE;
BEGIN
 PERFORM 1 FROM public."RegisteredFundAccount" WHERE "id" = NEW."accountId" FOR UPDATE;
 SELECT "paymentRequestId" INTO STRICT request_id FROM public."PaymentExecution" WHERE "id" = NEW."executionId";
 SELECT "projectId" INTO STRICT project_id FROM public."PaymentRequest" WHERE "id"=request_id;
 SELECT scope."effectiveDate" INTO STRICT effective_date FROM public."jg_registered_operating_scope_lock"(project_id) scope;
 IF NEW."operatingLedgerEffectiveDateAtRegistration" IS DISTINCT FROM effective_date THEN RAISE EXCEPTION 'registered operating scope must freeze the real native project date'; END IF;
 SELECT "status" INTO round_status FROM public."ApprovalInstance" WHERE "businessType" = 'payment_request' AND "businessId" = request_id AND "flowType" = 'payment.approve' ORDER BY "createdAt" DESC LIMIT 1 FOR SHARE;
 IF round_status IS DISTINCT FROM 'approved' THEN RAISE EXCEPTION 'registered payment latest approval round is not approved'; END IF;
 SELECT * INTO r FROM public."FundAccountBalanceRegistration" WHERE "accountId" = NEW."accountId" AND "status" = 'confirmed' ORDER BY "version" DESC LIMIT 1;
 IF r."id" IS NULL OR r."id" <> NEW."balanceRegistrationId" OR NOT EXISTS (
   SELECT 1 FROM public."RegisteredFundAccount" WHERE "id" = NEW."accountId" AND "writeRevision" > 0 AND xmin::TEXT = (pg_catalog.txid_current() % 4294967296)::TEXT
 ) OR NOT EXISTS (
   SELECT 1 FROM public."PaymentExecution" WHERE "id" = NEW."executionId" AND xmin::text = (pg_catalog.txid_current() % 4294967296)::text
 ) THEN RAISE EXCEPTION 'registered payment must atomically freeze the current same-account reconciliation'; END IF;
 RETURN NEW;
END

DECLARE acc_id TEXT; r public."FundAccountBalanceRegistration"; paid NUMERIC;
BEGIN
 acc_id := NEW."accountId";
 PERFORM 1 FROM public."RegisteredFundAccount" WHERE "id" = acc_id FOR UPDATE;
 SELECT * INTO r FROM public."FundAccountBalanceRegistration" WHERE "accountId" = acc_id AND "status" = 'confirmed' ORDER BY "version" DESC LIMIT 1;
 IF r."id" IS NULL THEN RAISE EXCEPTION 'registered payment account has no confirmed reconciliation'; END IF;
 SELECT coalesce(pg_catalog.sum(p."amountCents"),0) INTO paid FROM public."RegisteredFundPaymentAllocation" p
 WHERE p."accountId" = acc_id AND NOT (p."executionId" = ANY(r."coveredExecutionIds"));
 -- Unknown reconciliation remains unknown with existing uncovered payments;
 -- it is not zero or insufficient. New uncovered postings still require a
 -- known balance at INSERT below. A known negative result cannot be confirmed.
 IF r."balanceYuan" IS NOT NULL AND r."balanceYuan" * 100 < paid THEN
   RAISE EXCEPTION 'registered payment exceeds the confirmed account capacity';
 END IF;
 IF EXISTS (
   WITH RECURSIVE ancestry(current_id,node_id,path) AS (
     SELECT s."id",s."id",ARRAY[s."id"] FROM public."FundAccountSourceBatch" s WHERE s."registrationId" = r."id"
     UNION ALL
     SELECT a.current_id,s."previousSourceBatchId",a.path || s."previousSourceBatchId"
       FROM ancestry a JOIN public."FundAccountSourceBatch" s ON s."id" = a.node_id
       WHERE s."previousSourceBatchId" IS NOT NULL AND NOT(s."previousSourceBatchId" = ANY(a.path))
   ), matches AS (
     SELECT p."id" AS allocation_id,p."amountCents",a.current_id,
            pg_catalog.count(*) OVER(PARTITION BY p."id") AS candidate_count
       FROM public."RegisteredFundPaymentAllocation" p JOIN ancestry a ON a.node_id = p."sourceBatchId"
       WHERE p."accountId" = acc_id AND NOT(p."executionId" = ANY(r."coveredExecutionIds"))
   )
   SELECT 1 FROM matches m JOIN public."FundAccountSourceBatch" s ON s."id" = m.current_id
   WHERE m.candidate_count = 1 GROUP BY s."id",s."amountYuan" HAVING pg_catalog.sum(m."amountCents") > s."amountYuan" * 100
 ) THEN RAISE EXCEPTION 'registered payment exceeds its unambiguous source capacity'; END IF;
 RETURN NULL;
END

DECLARE f public."RegisteredPaymentFunding"; r public."FundAccountBalanceRegistration"; s public."FundAccountSourceBatch"; project_id TEXT;
BEGIN
 SELECT * INTO STRICT f FROM public."RegisteredPaymentFunding" WHERE "executionId" = NEW."executionId" AND "accountId" = NEW."accountId";
 SELECT * INTO STRICT r FROM public."FundAccountBalanceRegistration" WHERE "id" = f."balanceRegistrationId" AND "accountId" = f."accountId";
 IF r."balanceYuan" IS NULL THEN RAISE EXCEPTION 'unknown reconciliation cannot fund a new uncovered payment'; END IF;
 SELECT * INTO STRICT s FROM public."FundAccountSourceBatch" WHERE "id" = NEW."sourceBatchId";
 IF s."registrationId" <> r."id" OR f."openingTreatment" <> 'not_included' THEN RAISE EXCEPTION 'allocation requires this payment frozen source'; END IF;
 SELECT request."projectId" INTO STRICT project_id FROM public."PaymentExecution" e JOIN public."PaymentRequest" request ON request."id" = e."paymentRequestId" WHERE e."id" = f."executionId";
 IF s."projectStatus" = 'company_daily' OR (s."projectStatus" = 'project' AND s."projectId" IS DISTINCT FROM project_id) THEN RAISE EXCEPTION 'payment project shortage cannot create an automatic advance or receipt'; END IF;
 IF EXISTS (
   WITH RECURSIVE ancestry(current_id,node_id,path) AS (
     SELECT source."id",source."id",ARRAY[source."id"] FROM public."FundAccountSourceBatch" source WHERE source."registrationId" = r."id"
     UNION ALL SELECT a.current_id,parent."previousSourceBatchId",a.path || parent."previousSourceBatchId"
       FROM ancestry a JOIN public."FundAccountSourceBatch" parent ON parent."id" = a.node_id
       WHERE parent."previousSourceBatchId" IS NOT NULL AND NOT(parent."previousSourceBatchId" = ANY(a.path))
   ), candidates AS (
     SELECT p."id",coalesce(pg_catalog.array_agg(a.current_id) FILTER(WHERE a.current_id IS NOT NULL),ARRAY[]::TEXT[]) AS candidate_ids FROM public."RegisteredFundPaymentAllocation" p
       LEFT JOIN ancestry a ON a.node_id = p."sourceBatchId"
       WHERE p."accountId" = f."accountId" AND NOT(p."executionId" = ANY(r."coveredExecutionIds"))
       GROUP BY p."id"
   ) SELECT 1 FROM candidates c WHERE pg_catalog.cardinality(c.candidate_ids) = 0 OR (pg_catalog.cardinality(c.candidate_ids) <> 1 AND NEW."sourceBatchId" = ANY(c.candidate_ids))
 ) THEN RAISE EXCEPTION 'source distribution is unresolved after reconciliation; no automatic allocation is allowed'; END IF;
 RETURN NEW;
END

BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'RegisteredContractHistoryRevision' THEN RAISE EXCEPTION 'history revision guard attached to wrong relation'; END IF;
 IF TG_OP = 'INSERT' AND pg_catalog.pg_trigger_depth() >= 2 AND NEW."revision" = 0 AND EXISTS(SELECT 1 FROM public."Contract" WHERE "id" = NEW."contractId") THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND pg_catalog.pg_trigger_depth() >= 2 AND NEW."contractId" = OLD."contractId" AND NEW."revision" = OLD."revision" + 1 THEN RETURN NEW; END IF;
 -- Preserve legitimate original Contract deletion; no payment/history row is
 -- removed by this technical table's cascade. Runtime direct DELETE is denied.
 IF TG_OP = 'DELETE' AND NOT EXISTS(SELECT 1 FROM public."Contract" WHERE "id" = OLD."contractId") THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'history revision is controlled by its real parent triggers';
END

BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'Contract' OR TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'history marker creation requires real new Contract'; END IF;
 INSERT INTO public."RegisteredContractHistoryRevision"("contractId","revision") VALUES(NEW."id",0);
 RETURN NEW;
END

DECLARE current_revision BIGINT;
BEGIN
 BEGIN
   SELECT "revision" INTO current_revision FROM public."RegisteredContractHistoryRevision" WHERE "contractId" = contract_id FOR UPDATE NOWAIT;
 EXCEPTION WHEN lock_not_available THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='contract history basis is being changed; query original result before retry';
 END;
 RETURN current_revision; -- missing marker remains NULL, never inserted here
END

BEGIN
 IF pg_catalog.current_setting('transaction_isolation') <> 'serializable' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='registered payment history basis requires Serializable transaction'; END IF;
 RETURN public."jg_registered_history_try_lock_internal"(contract_id);
END

SELECT pg_catalog.jsonb_build_array(row_value->'id',row_value->'contractId',row_value->'contractVersionId',row_value->'paymentTermsVersionId',
  row_value->'takeoverStatus',row_value->'historicalBalanceConfirmedAt',row_value->'activatedAt',row_value->'updatedAt',
  row_value->'historicalPaidCents',row_value->'historicalProxyPaidCents',row_value->'historicalAdvancePaidCents');

DECLARE old_row JSONB; new_row JSONB; old_member BOOLEAN := FALSE; new_member BOOLEAN := FALSE; parent_id TEXT; revision_seen BIGINT;
BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'ContractTakeover' THEN RAISE EXCEPTION 'history revision writer attached to wrong relation'; END IF;
 IF TG_OP <> 'INSERT' THEN old_row := pg_catalog.to_jsonb(OLD); old_member := public."jg_registered_history_basis_member"(old_row); END IF;
 IF TG_OP <> 'DELETE' THEN new_row := pg_catalog.to_jsonb(NEW); new_member := public."jg_registered_history_basis_member"(new_row); END IF;
 IF (old_member OR new_member) AND (TG_OP <> 'UPDATE' OR public."jg_registered_history_basis_tuple"(old_row) IS DISTINCT FROM public."jg_registered_history_basis_tuple"(new_row)) THEN
   FOR parent_id IN SELECT DISTINCT value FROM pg_catalog.unnest(ARRAY[CASE WHEN old_member THEN old_row->>'contractId' END,CASE WHEN new_member THEN new_row->>'contractId' END]) AS parent(value) WHERE value IS NOT NULL ORDER BY value LOOP
     revision_seen := public."jg_registered_history_try_lock_internal"(parent_id);
     IF revision_seen IS NULL THEN RAISE EXCEPTION 'contract history revision marker is missing'; END IF;
     UPDATE public."RegisteredContractHistoryRevision" SET "revision" = "revision" + 1 WHERE "contractId" = parent_id;
   END LOOP;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END

DECLARE e public."PaymentExecution"; f public."RegisteredPaymentFunding"; request public."PaymentRequest";
 root public."InterEntityRelationshipEntry"; fact public."OperatingFact"; effect public."OperatingImpactEntry";
 frozen_source_type TEXT; cross_company BOOLEAN; root_count BIGINT; fact_count BIGINT; impact_count BIGINT;
 due_count BIGINT; due_total NUMERIC; expected_payables JSONB; snapshot_payables JSONB; expected_payable_count BIGINT;
 payable_count BIGINT := 0; funds_count BIGINT := 0; proxy_count BIGINT := 0; source_id TEXT; funds_kind TEXT;
BEGIN
 SELECT * INTO STRICT e FROM public."PaymentExecution" WHERE "id" = execution_id;
 SELECT * INTO STRICT f FROM public."RegisteredPaymentFunding" WHERE "executionId" = execution_id;
 SELECT * INTO STRICT request FROM public."PaymentRequest" WHERE "id" = e."paymentRequestId";
 SELECT event."payload"->'writeAuthority'->>'sourceType' INTO STRICT frozen_source_type
 FROM public."RegisteredPaymentEvent" event WHERE event."executionId"=execution_id;
 IF frozen_source_type NOT IN ('settlement','contract_due','contract_advance') OR frozen_source_type IS NULL THEN
   RAISE EXCEPTION 'registered payment requires its frozen source applicability';
 END IF;
 cross_company := f."actualPayerKind"='participating_company' AND f."actualPayerId"<>e."companyEntityIdSnapshot";
 SELECT pg_catalog.count(*) INTO root_count FROM public."InterEntityRelationshipEntry"
 WHERE "paymentExecutionId"=execution_id AND "entryKind"='proxy_payment' AND "direction"='increase';
 IF cross_company THEN
   IF root_count<>1 THEN RAISE EXCEPTION 'registered cross-company payment requires exactly one debt root'; END IF;
   SELECT * INTO STRICT root FROM public."InterEntityRelationshipEntry"
   WHERE "paymentExecutionId"=execution_id AND "entryKind"='proxy_payment' AND "direction"='increase';
   PERFORM public."jg_assert_registered_payment_relationship"(root);
 ELSIF root_count<>0 THEN
   RAISE EXCEPTION 'same-company or public-cash payment cannot create an intercompany debt root';
 END IF;
 -- Adapter's payable basis is immutable Execution.settlementId plus positive
 -- immutable due-payment allocation rows, never a guessed zero or future request.
 SELECT pg_catalog.count(*),coalesce(pg_catalog.sum(a."amountCents"),0) INTO due_count,due_total
 FROM public."PaymentExecutionAllocation" a WHERE a."paymentExecutionId"=execution_id AND a."allocationType"='contract_due_payment';
 IF EXISTS(SELECT 1 FROM public."PaymentExecutionAllocation" a WHERE a."paymentExecutionId"=execution_id AND a."allocationType"='contract_due_payment'
   AND (a."paymentRequestId"<>e."paymentRequestId" OR a."projectId"<>request."projectId" OR a."contractId"<>request."contractId"
        OR a."amountCents"<=0 OR coalesce(pg_catalog.length(pg_catalog.btrim(coalesce(a."settlementId",a."sourceRowId"))),0)=0)) THEN
   RAISE EXCEPTION 'registered due allocation must belong to its frozen payment source';
 END IF;
 IF frozen_source_type='contract_due' AND e."settlementId" IS NULL THEN
   IF due_count=0 OR due_total<>e."amountCents" THEN RAISE EXCEPTION 'registered contract-due payment requires its full immutable payable allocation basis'; END IF;
 ELSIF due_count<>0 THEN
   RAISE EXCEPTION 'registered payment cannot add a due allocation outside its application source path';
 END IF;
 SELECT coalesce(pg_catalog.jsonb_object_agg(grouped.source_id,grouped.amount::TEXT),'{}'::JSONB) INTO expected_payables
 FROM (SELECT pg_catalog.btrim(coalesce(a."settlementId",a."sourceRowId")) AS source_id,pg_catalog.sum(a."amountCents") AS amount
       FROM public."PaymentExecutionAllocation" a WHERE a."paymentExecutionId"=execution_id AND a."allocationType"='contract_due_payment'
       GROUP BY pg_catalog.btrim(coalesce(a."settlementId",a."sourceRowId"))) grouped;
 IF due_count=0 AND e."settlementId" IS NOT NULL THEN
   IF pg_catalog.length(pg_catalog.btrim(e."settlementId"))=0 THEN RAISE EXCEPTION 'registered settlement source is empty'; END IF;
   expected_payables:=pg_catalog.jsonb_build_object(pg_catalog.btrim(e."settlementId"),e."amountCents"::TEXT);
 END IF;
 SELECT pg_catalog.count(*) INTO fact_count FROM public."OperatingFact" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id;
 SELECT pg_catalog.count(*) INTO impact_count FROM public."OperatingImpactEntry" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id;
 -- NULL frozen scope permits no projection at all. Once any projection exists,
 -- including a later legitimate append, it must be the complete same graph.
 IF f."operatingLedgerEffectiveDateAtRegistration" IS NULL AND fact_count=0 AND impact_count=0 THEN RETURN; END IF;
 IF fact_count<>1 THEN RAISE EXCEPTION 'registered projected payment requires exactly one canonical fact'; END IF;
 SELECT * INTO STRICT fact FROM public."OperatingFact" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id;
 IF NOT coalesce(fact."projectId"=request."projectId" AND fact."sourceVersion"=1 AND fact."entryKind"='original' AND fact."status"='confirmed'
   AND fact."factKind"='downstream_payment' AND fact."operatingLevel"=CASE WHEN cross_company THEN 'inter_subject' ELSE 'project' END
   AND fact."amountCents"=e."amountCents" AND fact."currencyCode"='CNY' AND fact."direction"='outflow' AND fact."evidenceLevel"='A'
   AND fact."occurredAt"=e."paidAt" AND fact."confirmedAt"=e."createdAt" AND fact."confirmedByUserId"=e."executedByUserId" AND fact."recordedByUserId"=e."executedByUserId"
   AND fact."idempotencyKey"='payment_execution:'||execution_id
   AND fact."debtorSubjectKind"='participating_company' AND fact."debtorSubjectId"=e."companyEntityIdSnapshot"
   AND fact."approvedPayerSubjectKind"='participating_company' AND fact."approvedPayerSubjectId"=e."companyEntityIdSnapshot"
   AND fact."actualPayerSubjectKind"=f."actualPayerKind" AND fact."actualPayerSubjectId"=f."actualPayerId"
   AND fact."payeeSubjectKind"='downstream_counterparty' AND pg_catalog.length(pg_catalog.btrim(fact."payeeSubjectId"))>0
   AND fact."sourceSnapshot"->>'payeeVersionId'=fact."payeeSubjectId"
   AND fact."sourceSnapshot"->>'paymentSourceType'=frozen_source_type
   AND fact."sourceSnapshot"->'settlementId'=coalesce(pg_catalog.to_jsonb(e."settlementId"),'null'::JSONB)
   AND (f."operatingLedgerEffectiveDateAtRegistration" IS NULL OR fact."operatingLedgerEffectiveDateSnapshot"=f."operatingLedgerEffectiveDateAtRegistration")
   AND public."jg_registered_payment_source_matches"(execution_id,request."projectId",e."amountCents",f."actualPayerKind",f."actualPayerId"),FALSE) THEN
   RAISE EXCEPTION 'registered canonical fact must match its exact frozen payment subjects and applicability';
 END IF;
 IF pg_catalog.jsonb_typeof(fact."sourceSnapshot"->'payableAllocations') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'registered canonical fact requires its payable source set'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(fact."sourceSnapshot"->'payableAllocations') item
   WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object' OR pg_catalog.jsonb_typeof(item->'sourceId') IS DISTINCT FROM 'string'
     OR coalesce(pg_catalog.length(pg_catalog.btrim(item->>'sourceId')),0)=0 OR pg_catalog.jsonb_typeof(item->'amountCents') IS DISTINCT FROM 'string'
     OR NOT coalesce(item->>'amountCents' ~ '^[1-9][0-9]*$',FALSE)) THEN RAISE EXCEPTION 'registered canonical payable source is invalid'; END IF;
 SELECT coalesce(pg_catalog.jsonb_object_agg(grouped.source_id,grouped.amount::TEXT),'{}'::JSONB) INTO snapshot_payables
 FROM (SELECT pg_catalog.btrim(item->>'sourceId') AS source_id,pg_catalog.sum((item->>'amountCents')::NUMERIC) AS amount
       FROM pg_catalog.jsonb_array_elements(fact."sourceSnapshot"->'payableAllocations') item GROUP BY pg_catalog.btrim(item->>'sourceId')) grouped;
 IF snapshot_payables<>expected_payables THEN RAISE EXCEPTION 'registered canonical payable snapshot must match its immutable execution allocations'; END IF;
 funds_kind:=CASE WHEN f."actualPayerKind"='public_cash' THEN 'public_cash_funds_decrease' ELSE 'company_project_funds_decrease' END;
 FOR effect IN SELECT * FROM public."OperatingImpactEntry" WHERE "sourceType"='payment_execution' AND "sourceBusinessId"=execution_id LOOP
   IF effect."factId"<>fact."id" OR effect."projectId"<>fact."projectId" THEN RAISE EXCEPTION 'registered impact must belong to its one canonical fact'; END IF;
   IF effect."sourceImpactKey" LIKE 'payable:%' THEN
     source_id:=pg_catalog.substr(effect."sourceImpactKey",9);
     IF NOT coalesce(expected_payables ? source_id AND effect."impactKind"='payable_decrease' AND effect."direction"='decrease'
       AND effect."idempotencyKey"='payment_execution:'||execution_id||':payable:'||source_id
       AND effect."amountCents"=(expected_payables->>source_id)::BIGINT AND effect."subjectRole"='payee'
       AND effect."subjectKind"=fact."payeeSubjectKind" AND effect."subjectId"=fact."payeeSubjectId",FALSE) THEN
       RAISE EXCEPTION 'registered payable impact must match its exact immutable allocation and frozen fact payee'; END IF;
     payable_count:=payable_count+1;
   ELSIF effect."sourceImpactKey"=funds_kind THEN
     IF NOT coalesce(f."openingTreatment"='not_included' AND effect."impactKind"=funds_kind AND effect."direction"='decrease'
       AND effect."idempotencyKey"='payment_execution:'||execution_id||':funds' AND effect."amountCents"=e."amountCents"
       AND effect."subjectRole"='actual_payer' AND effect."subjectKind"=f."actualPayerKind" AND effect."subjectId"=f."actualPayerId",FALSE) THEN
       RAISE EXCEPTION 'registered funds impact must match the unpaid-in-opening frozen actual payer'; END IF;
     funds_count:=funds_count+1;
   ELSIF effect."sourceImpactKey"='inter_subject_proxy_payment' THEN
     IF NOT coalesce(cross_company AND effect."impactKind"='inter_subject_balance_increase' AND effect."direction"='increase'
       AND effect."idempotencyKey"='payment_execution:'||execution_id||':proxy' AND effect."amountCents"=e."amountCents"
       AND effect."subjectRole"='actual_payer' AND effect."subjectKind"='participating_company' AND effect."subjectId"=f."actualPayerId"
       AND effect."impactSnapshot"->'debtor'=pg_catalog.jsonb_build_object('kind','participating_company','id',e."companyEntityIdSnapshot")
       AND effect."impactSnapshot"->'approvedPayer'=pg_catalog.jsonb_build_object('kind','participating_company','id',e."companyEntityIdSnapshot")
       AND effect."impactSnapshot"->'actualPayer'=pg_catalog.jsonb_build_object('kind','participating_company','id',f."actualPayerId"),FALSE) THEN
       RAISE EXCEPTION 'registered proxy impact must match its one frozen debt root'; END IF;
     proxy_count:=proxy_count+1;
   ELSE RAISE EXCEPTION 'registered canonical graph cannot contain an extra unrecognized impact'; END IF;
 END LOOP;
 SELECT pg_catalog.count(*) INTO expected_payable_count FROM pg_catalog.jsonb_object_keys(expected_payables);
 IF payable_count<>expected_payable_count OR funds_count<>CASE WHEN f."openingTreatment"='not_included' THEN 1 ELSE 0 END
   OR proxy_count<>CASE WHEN cross_company THEN 1 ELSE 0 END THEN
   RAISE EXCEPTION 'registered canonical graph is missing an applicable payable, funds or proxy consequence';
 END IF;
END

BEGIN
 IF EXISTS(SELECT 1 FROM public."RegisteredPaymentFunding" f WHERE f."executionId"=NEW."paymentExecutionId") THEN
   PERFORM public."jg_assert_registered_payment_intercompany_complete"(NEW."paymentExecutionId");
 END IF;
 RETURN NULL;
END

BEGIN
 IF NEW."sourceType" = 'registered_payment_execution' AND NEW."entryKind" = 'proxy_payment' THEN
   PERFORM public."jg_assert_registered_payment_relationship"(NEW);
   IF EXISTS(SELECT 1 FROM public."PaymentExecutionWagePayableBinding" WHERE "paymentExecutionId" = NEW."paymentExecutionId") THEN
     RAISE EXCEPTION 'registered company payment cannot bypass canonical wage allocation authority';
   END IF;
 END IF;
 RETURN NULL;
END

DECLARE payment public."PaymentExecution"; file public."FileObject";
BEGIN
 SELECT * INTO STRICT payment FROM public."PaymentExecution" WHERE "id" = NEW."executionId" FOR UPDATE;
 IF payment."voucherFileId" IS NOT NULL OR NOT EXISTS (SELECT 1 FROM public."RegisteredPaymentFunding" WHERE "executionId" = payment."id") THEN
   RAISE EXCEPTION 'supplemental evidence requires the same registered pending-voucher payment';
 END IF;
 -- Same business-row -> shared file advisory -> FileObject lock order as the service.
 PERFORM pg_catalog.pg_advisory_xact_lock(190731,13);
 SELECT * INTO STRICT file FROM public."FileObject" WHERE "id" = NEW."fileId" FOR UPDATE;
 IF file."storageStatus" IS DISTINCT FROM 'active' OR file."contentSha256" IS DISTINCT FROM NEW."contentSha256" OR
    file."uploadedByUserId" IS DISTINCT FROM NEW."uploadedByUserId" OR file."supersedesFileObjectId" IS NOT NULL OR
    NOT EXISTS (SELECT 1 FROM public."User" WHERE "id" = NEW."uploadedByUserId" AND "isActive" = TRUE) THEN
   RAISE EXCEPTION 'supplemental voucher requires the current uploader private immutable file identity';
 END IF;
 -- The exclusive-binding trigger takes the shared file lock and rechecks all
 -- existing domains. No empty file identifier or client source flag is proof.
 RETURN NEW;
END

BEGIN
 IF EXISTS(SELECT 1 FROM public."RegisteredPaymentVoucher" WHERE "fileId" = OLD."id") THEN
   IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'registered payment voucher metadata is immutable'; END IF;
   IF pg_catalog.to_jsonb(NEW) IS DISTINCT FROM pg_catalog.to_jsonb(OLD) THEN RAISE EXCEPTION 'registered payment voucher metadata is immutable'; END IF;
 END IF;
 RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END

BEGIN
 IF NOT pg_catalog.isfinite(p_value) OR extract(year FROM p_value) NOT BETWEEN 1 AND 9999 THEN RAISE EXCEPTION 'registered payment timestamp is outside reviewed ISO encoding'; END IF;
 RETURN pg_catalog.to_char(p_value,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
END

DECLARE utc_value TIMESTAMP WITHOUT TIME ZONE;
BEGIN
 IF NOT pg_catalog.isfinite(p_value) THEN RAISE EXCEPTION 'registered payment timestamp is outside reviewed ISO encoding'; END IF;
 utc_value:=p_value AT TIME ZONE 'UTC';
 IF extract(year FROM utc_value) NOT BETWEEN 1 AND 9999 THEN RAISE EXCEPTION 'registered payment timestamp is outside reviewed ISO encoding'; END IF;
 RETURN pg_catalog.to_char(utc_value,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
END

DECLARE contract_id TEXT; basis JSONB; proof JSONB; revision_seen BIGINT;
BEGIN
 SELECT request."contractId" INTO STRICT contract_id FROM public."PaymentExecution" e JOIN public."PaymentRequest" request ON request."id" = e."paymentRequestId" WHERE e."id" = NEW."executionId";
 revision_seen := public."jg_registered_history_lock_revision"(contract_id);
 IF revision_seen IS NULL THEN RAISE EXCEPTION 'registered contract history marker is missing'; END IF;
 -- No history-row lock after marker: writers use NOWAIT and cannot wait here.
 basis := public."jg_registered_contract_history_basis"(contract_id);
 proof := NEW."contractHistoryConfirmation";
 IF (basis->>'required')::BOOLEAN OR proof IS NOT NULL THEN
   IF NOT coalesce(pg_catalog.jsonb_typeof(proof) = 'object' AND proof->>'treatment' = 'not_included'
      AND pg_catalog.jsonb_typeof(proof->'reason') = 'string' AND pg_catalog.jsonb_typeof(proof->'evidence') = 'string'
      AND pg_catalog.length(pg_catalog.btrim(proof->>'reason')) BETWEEN 1 AND 500 AND pg_catalog.length(pg_catalog.btrim(proof->>'evidence')) BETWEEN 1 AND 1000
      AND proof->'basis' = basis,FALSE) THEN
     RAISE EXCEPTION 'registered payment requires independent exact contract history confirmation';
   END IF;
 END IF;
 RETURN NEW;
END

DECLARE e public."PaymentExecution"; request public."PaymentRequest"; version public."ContractVersion"; round public."ApprovalInstance";
 frozen_round JSONB; newest_time TIMESTAMP(3); newest_count BIGINT; marker_revision BIGINT; history_basis JSONB; history_confirmation JSONB; company public."CompanyEntity"; frozen_company public."CompanyEntityVersion"; payer_company_id TEXT; project_effective_date DATE; frozen_effective_date DATE;
BEGIN
 IF pg_catalog.current_setting('transaction_isolation') <> 'serializable' THEN RAISE EXCEPTION 'registered payment requires Serializable authority read-set'; END IF;
 SELECT * INTO STRICT e FROM public."PaymentExecution" WHERE "id" = execution_id;
 SELECT * INTO STRICT request FROM public."PaymentRequest" WHERE "id" = e."paymentRequestId" FOR UPDATE;
 SELECT scope."effectiveDate" INTO STRICT project_effective_date FROM public."jg_registered_operating_scope_lock"(request."projectId") scope;
 SELECT "operatingLedgerEffectiveDateAtRegistration" INTO STRICT frozen_effective_date FROM public."RegisteredPaymentFunding" WHERE "executionId"=execution_id;
 IF frozen_effective_date IS DISTINCT FROM project_effective_date THEN RAISE EXCEPTION 'registered project operating scope changed before commit'; END IF;
 SELECT * INTO STRICT version FROM public."ContractVersion" WHERE "id" = request."contractVersionId" FOR SHARE;
 marker_revision := public."jg_registered_history_lock_revision"(request."contractId");
 IF marker_revision IS NULL OR pg_catalog.jsonb_typeof(authority->'contractHistoryRevision') IS DISTINCT FROM 'string'
   OR authority->>'contractHistoryRevision' IS DISTINCT FROM marker_revision::TEXT THEN
   RAISE EXCEPTION 'registered payment event has a missing or stale complete history revision';
 END IF;
 history_basis := public."jg_registered_contract_history_basis"(request."contractId");
 SELECT "contractHistoryConfirmation" INTO history_confirmation FROM public."RegisteredPaymentFunding" WHERE "executionId" = execution_id;
 IF (history_basis->>'required')::BOOLEAN OR history_confirmation IS NOT NULL THEN
   IF NOT coalesce(history_confirmation->>'treatment' = 'not_included' AND history_confirmation->'basis' = history_basis
     AND pg_catalog.jsonb_typeof(history_confirmation->'reason') = 'string' AND pg_catalog.length(pg_catalog.btrim(history_confirmation->>'reason')) BETWEEN 1 AND 500
     AND pg_catalog.jsonb_typeof(history_confirmation->'evidence') = 'string' AND pg_catalog.length(pg_catalog.btrim(history_confirmation->>'evidence')) BETWEEN 1 AND 1000,FALSE) THEN
     RAISE EXCEPTION 'registered payment history set changed before commit';
   END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public."PaymentExecution" WHERE "id" = execution_id AND xmin::TEXT = (pg_catalog.txid_current() % 4294967296)::TEXT)
 OR request."paymentSubjectType" <> 'our_company' OR e."paymentSubjectType" <> 'our_company'
 OR request."sourceType" NOT IN ('settlement','contract_due','contract_advance') OR version."contractId" <> request."contractId"
 OR version."signingSubjectType" IS DISTINCT FROM 'our_company' OR NOT public."jg_registered_payment_actor_current"(e."executedByUserId")
 OR NOT EXISTS(SELECT 1 FROM public."Contract" contract WHERE contract."id" = request."contractId" AND contract."projectId" = request."projectId")
 OR e."companyEntityIdSnapshot" IS DISTINCT FROM version."companyEntityIdSnapshot"
 OR e."companyEntityNameSnapshot" IS DISTINCT FROM version."companyEntityNameSnapshot"
 OR e."companyEntityCreditCodeSnapshot" IS DISTINCT FROM version."companyEntityCreditCodeSnapshot"
 OR EXISTS(SELECT 1 FROM public."PaymentExecution" prior JOIN public."PaymentExecutionWagePayableBinding" wage ON wage."paymentExecutionId" = prior."id" WHERE prior."paymentRequestId" = request."id")
 OR EXISTS(SELECT 1 FROM public."PaymentExecution" prior JOIN public."HistoricalWageSummaryPaymentExecutionLink" wage ON wage."paymentExecutionId" = prior."id" WHERE prior."paymentRequestId" = request."id")
 THEN RAISE EXCEPTION 'registered payment current domain or actor authority is invalid'; END IF;
 IF before_update AND request."status" NOT IN ('approved_pending_payment','partially_paid') THEN RAISE EXCEPTION 'registered payment request is not awaiting execution'; END IF;
 PERFORM 1 FROM public."User" WHERE "id" = e."executedByUserId" FOR SHARE;
 PERFORM 1 FROM public."UserPosition" WHERE "userId" = e."executedByUserId" AND "projectId" IS NULL ORDER BY "id" FOR SHARE;
 SELECT pg_catalog.max("createdAt") INTO newest_time FROM public."ApprovalInstance" WHERE "businessType" = 'payment_request' AND "businessId" = request."id" AND "flowType" = 'payment.approve';
 SELECT pg_catalog.count(*) INTO newest_count FROM public."ApprovalInstance" WHERE "businessType" = 'payment_request' AND "businessId" = request."id" AND "flowType" = 'payment.approve' AND "createdAt" = newest_time;
 IF newest_count <> 1 THEN RAISE EXCEPTION 'registered payment latest approval round is missing or ambiguous'; END IF;
 SELECT * INTO STRICT round FROM public."ApprovalInstance" WHERE "businessType" = 'payment_request' AND "businessId" = request."id" AND "flowType" = 'payment.approve' AND "createdAt" = newest_time FOR SHARE;
 frozen_round := pg_catalog.jsonb_build_object('id',round."id",'businessType',round."businessType",'businessId',round."businessId",'flowType',round."flowType",'status',round."status",'createdAt',public."jg_registered_timestamp_iso"(round."createdAt"));
 IF round."status" <> 'approved' OR NOT coalesce(pg_catalog.jsonb_typeof(authority) = 'object' AND authority->'schemaVersion' = '1'::JSONB
   AND authority->>'paymentRequestId' = request."id" AND authority->>'projectId' = request."projectId"
   AND authority->>'contractId' = request."contractId" AND authority->>'contractVersionId' = version."id"
   AND authority->>'sourceType' = request."sourceType" AND authority->>'paymentSubjectType' = 'our_company'
   AND authority->>'signingSubjectType' = 'our_company' AND authority->'approvalRound' = frozen_round
   AND authority->>'requestStatusBeforeExecution' IN ('approved_pending_payment','partially_paid'),FALSE)
 THEN RAISE EXCEPTION 'registered payment event cannot self-assert approval or domain coordinates'; END IF;
 IF before_update AND authority->>'requestStatusBeforeExecution' IS DISTINCT FROM request."status" THEN RAISE EXCEPTION 'registered payment event has a different original status'; END IF;
 IF NOT coalesce(pg_catalog.jsonb_typeof(authority->'paidAmountBeforeExecution') = 'string' AND pg_catalog.jsonb_typeof(authority->'approvedAmountCents') = 'string'
   AND authority->>'paidAmountBeforeExecution' ~ '^[0-9]+$' AND authority->>'approvedAmountCents' ~ '^[0-9]+$'
   AND authority->>'approvedAmountCents' = coalesce(request."approvedAmountCents",request."requestedAmountCents")::TEXT,FALSE) THEN
   RAISE EXCEPTION 'registered payment event requires server request capacity coordinates';
 END IF;
 IF before_update THEN
   IF authority->>'paidAmountBeforeExecution' IS DISTINCT FROM request."paidAmountCents"::TEXT OR
      request."paidAmountCents"::NUMERIC + e."amountCents" > coalesce(request."approvedAmountCents",request."requestedAmountCents")::NUMERIC THEN
     RAISE EXCEPTION 'registered payment exceeds original approved request capacity';
   END IF;
 ELSE
   IF request."paidAmountCents"::NUMERIC <> (authority->>'paidAmountBeforeExecution')::NUMERIC + e."amountCents" OR
      request."paidAmountCents" > coalesce(request."approvedAmountCents",request."requestedAmountCents") OR
      request."status" IS DISTINCT FROM CASE WHEN request."paidAmountCents" >= coalesce(request."approvedAmountCents",request."requestedAmountCents") THEN 'paid' ELSE 'partially_paid' END THEN
     RAISE EXCEPTION 'registered payment must commit exactly one matching request paid consequence';
   END IF;
 END IF;
 -- Preserve task07's frozen original inactive company continuation. A new
 -- inactive payer cannot become eligible merely by appearing in earlier rows.
 SELECT * INTO STRICT company FROM public."CompanyEntity" WHERE "id" = version."companyEntityIdSnapshot" FOR SHARE;
 IF NOT company."isActive" THEN
   SELECT * INTO frozen_company FROM public."CompanyEntityVersion" WHERE "id" = version."companyEntityVersionId" FOR SHARE;
   IF version."status" NOT IN ('effective','superseded') OR frozen_company."id" IS NULL OR NOT frozen_company."isActive"
      OR pg_catalog.length(pg_catalog.btrim(version."companyEntityNameSnapshot")) = 0 OR pg_catalog.length(pg_catalog.btrim(version."companyEntityCreditCodeSnapshot")) = 0
      OR frozen_company."companyEntityId" <> company."id" OR frozen_company."name" IS DISTINCT FROM version."companyEntityNameSnapshot"
      OR frozen_company."unifiedSocialCreditCode" IS DISTINCT FROM version."companyEntityCreditCodeSnapshot"
   THEN RAISE EXCEPTION 'registered payment inactive original company lacks frozen continuation proof'; END IF;
 END IF;
 SELECT account."companyEntityId" INTO payer_company_id FROM public."RegisteredPaymentFunding" funding JOIN public."RegisteredFundAccount" account ON account."id" = funding."accountId" WHERE funding."executionId" = execution_id;
 IF payer_company_id IS NOT NULL AND payer_company_id IS DISTINCT FROM version."companyEntityIdSnapshot" AND EXISTS(SELECT 1 FROM public."CompanyEntity" WHERE "id" = payer_company_id AND NOT "isActive") THEN
   RAISE EXCEPTION 'registered payment cannot newly choose an inactive proxy payer';
 END IF;
END

BEGIN
 PERFORM public."jg_assert_registered_payment_write_authority"(NEW."executionId",NEW."payload"->'writeAuthority',TG_WHEN = 'BEFORE');
 IF TG_WHEN = 'BEFORE' THEN RETURN NEW; END IF;
 RETURN NULL;
END

BEGIN
 IF EXISTS(SELECT 1 FROM public."RegisteredPaymentFunding" WHERE "executionId" = NEW."paymentExecutionId") THEN RAISE EXCEPTION 'registered payment and wage execution ownership are mutually exclusive'; END IF;
 RETURN NEW;
END

DECLARE
  project_effective_date DATE;
  project_is_active BOOLEAN;
  assignment_version_id TEXT;
  assignment_name TEXT;
  assignment_credit_code TEXT;
  candidate_company_id TEXT;
  candidate_subject JSONB;
  candidate_subject_role TEXT;
BEGIN
  SELECT "operatingLedgerEffectiveDate", "isActive"
    INTO project_effective_date, project_is_active
    FROM "Project"
    WHERE "id" = NEW."projectId"
    FOR UPDATE;
  IF project_is_active IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION '项目不存在或已停用，不能登记正式经营事实' USING ERRCODE = '23514';
  END IF;
  IF project_effective_date IS NULL THEN
    RAISE EXCEPTION '项目尚未启用经营账，不能登记正式经营事实' USING ERRCODE = '23514';
  END IF;
  IF NEW."operatingLedgerEffectiveDateSnapshot" IS DISTINCT FROM project_effective_date
     OR NEW."isBeforeOperatingLedgerEffectiveDate" IS DISTINCT FROM (
CASE WHEN public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact") IS NOT NULL
  OR public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END) IS NOT NULL
THEN ((NEW."occurredAt" AT TIME ZONE 'UTC') AT TIME ZONE 'Asia/Shanghai')::DATE
ELSE NEW."occurredAt"::DATE END < project_effective_date
) THEN
    RAISE EXCEPTION '经营事实的经营账生效日快照不一致' USING ERRCODE = '23514';
  END IF;
  FOREACH candidate_subject IN ARRAY ARRAY[
    CASE WHEN NEW."debtorSubjectKind" IS NOT NULL THEN jsonb_build_object('role', 'debtor', 'kind', NEW."debtorSubjectKind", 'id', NEW."debtorSubjectId") ELSE NULL END,
    CASE WHEN NEW."creditorSubjectKind" IS NOT NULL THEN jsonb_build_object('role', 'creditor', 'kind', NEW."creditorSubjectKind", 'id', NEW."creditorSubjectId") ELSE NULL END,
    CASE WHEN NEW."approvedPayerSubjectKind" IS NOT NULL THEN jsonb_build_object('role', 'approvedPayer', 'kind', NEW."approvedPayerSubjectKind", 'id', NEW."approvedPayerSubjectId") ELSE NULL END,
    CASE WHEN NEW."actualPayerSubjectKind" IS NOT NULL THEN jsonb_build_object('role', 'actualPayer', 'kind', NEW."actualPayerSubjectKind", 'id', NEW."actualPayerSubjectId") ELSE NULL END,
    CASE WHEN NEW."payeeSubjectKind" IS NOT NULL THEN jsonb_build_object('role', 'payee', 'kind', NEW."payeeSubjectKind", 'id', NEW."payeeSubjectId") ELSE NULL END,
    CASE WHEN NEW."costBearingCompanySubjectKind" IS NOT NULL THEN jsonb_build_object('role', 'costBearingCompany', 'kind', NEW."costBearingCompanySubjectKind", 'id', NEW."costBearingCompanySubjectId") ELSE NULL END
  ]::JSONB[] LOOP
    IF candidate_subject IS NULL THEN CONTINUE; END IF;
    IF candidate_subject->>'kind' NOT IN ('owner', 'construction_enterprise', 'participating_company', 'downstream_counterparty', 'employee', 'public_cash') THEN
      RAISE EXCEPTION '当前经营账尚未接入该主体种类，不能登记正式事实' USING ERRCODE = '23514';
    END IF;
    candidate_subject_role := candidate_subject->>'role';
    IF NEW."subjectSnapshot"->candidate_subject_role IS NULL
       OR NEW."subjectSnapshot"->candidate_subject_role->>'kind' IS DISTINCT FROM candidate_subject->>'kind'
       OR NEW."subjectSnapshot"->candidate_subject_role->>'id' IS DISTINCT FROM candidate_subject->>'id' THEN
      RAISE EXCEPTION '经营事实主体快照必须与主体字段一致' USING ERRCODE = '23514';
    END IF;
  END LOOP;

  SELECT "businessPartyVersionId", "affiliateNameSnapshot", "affiliateCreditCodeSnapshot"
    INTO assignment_version_id, assignment_name, assignment_credit_code
    FROM "ProjectAffiliateAssignment"
    WHERE "id" = NEW."affiliateAssignmentId"
      AND "projectId" = NEW."projectId"
      AND "effectiveFrom" <= COALESCE(public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact"), public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END), COALESCE(public.jg_contract_economic_review_ownership_date(NEW::public."OperatingFact"), public.jg_company_repayment_ownership_date(NEW."sourceType", NEW."sourceBusinessId", NEW."projectId"), NEW."occurredAt")::DATE)
      AND ("endedAt" IS NULL OR "endedAt" > COALESCE(public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact"), public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END), COALESCE(public.jg_contract_economic_review_ownership_date(NEW::public."OperatingFact"), public.jg_company_repayment_ownership_date(NEW."sourceType", NEW."sourceBusinessId", NEW."projectId"), NEW."occurredAt")::DATE))
    FOR KEY SHARE;
  IF assignment_version_id IS NULL
     OR assignment_version_id <> NEW."affiliateBusinessPartyVersionId"
     OR assignment_name IS DISTINCT FROM NEW."affiliateNameSnapshot"
     OR assignment_credit_code IS DISTINCT FROM NEW."affiliateCreditCodeSnapshot" THEN
    RAISE EXCEPTION '正式经营事实引用的施工企业已失效' USING ERRCODE = '23514';
  END IF;

  PERFORM participant."id"
    FROM "ProjectParticipatingCompany" participant
    WHERE participant."projectId" = NEW."projectId"
      AND (
        participant."companyEntityId" = ANY (ARRAY[
          CASE WHEN NEW."debtorSubjectKind" = 'participating_company' THEN NEW."debtorSubjectId" ELSE NULL END,
          CASE WHEN NEW."creditorSubjectKind" = 'participating_company' THEN NEW."creditorSubjectId" ELSE NULL END,
          CASE WHEN NEW."approvedPayerSubjectKind" = 'participating_company' THEN NEW."approvedPayerSubjectId" ELSE NULL END,
          CASE WHEN NEW."actualPayerSubjectKind" = 'participating_company' THEN CASE WHEN NEW."sourceType" = 'payment_execution' AND public."jg_registered_payment_source_matches"(NEW."sourceBusinessId",NEW."projectId",NEW."amountCents",NEW."actualPayerSubjectKind",NEW."actualPayerSubjectId") THEN NULL ELSE NEW."actualPayerSubjectId" END ELSE NULL END,
          CASE WHEN NEW."payeeSubjectKind" = 'participating_company' THEN NEW."payeeSubjectId" ELSE NULL END,
          CASE WHEN NEW."costBearingCompanySubjectKind" = 'participating_company' THEN NEW."costBearingCompanySubjectId" ELSE NULL END
        ]::TEXT[])
        OR participant."companyEntityVersionId" = ANY (ARRAY[
          CASE WHEN NEW."debtorSubjectKind" = 'participating_company' THEN NEW."debtorSubjectId" ELSE NULL END,
          CASE WHEN NEW."creditorSubjectKind" = 'participating_company' THEN NEW."creditorSubjectId" ELSE NULL END,
          CASE WHEN NEW."approvedPayerSubjectKind" = 'participating_company' THEN NEW."approvedPayerSubjectId" ELSE NULL END,
          CASE WHEN NEW."actualPayerSubjectKind" = 'participating_company' THEN CASE WHEN NEW."sourceType" = 'payment_execution' AND public."jg_registered_payment_source_matches"(NEW."sourceBusinessId",NEW."projectId",NEW."amountCents",NEW."actualPayerSubjectKind",NEW."actualPayerSubjectId") THEN NULL ELSE NEW."actualPayerSubjectId" END ELSE NULL END,
          CASE WHEN NEW."payeeSubjectKind" = 'participating_company' THEN NEW."payeeSubjectId" ELSE NULL END,
          CASE WHEN NEW."costBearingCompanySubjectKind" = 'participating_company' THEN NEW."costBearingCompanySubjectId" ELSE NULL END
        ]::TEXT[])
      )
      AND participant."effectiveFrom" <= COALESCE(public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact"), public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END), COALESCE(public.jg_contract_economic_review_ownership_date(NEW::public."OperatingFact"), public.jg_company_repayment_ownership_date(NEW."sourceType", NEW."sourceBusinessId", NEW."projectId"), NEW."occurredAt")::DATE)
      AND (participant."endedAt" IS NULL OR participant."endedAt" > COALESCE(public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact"), public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END), COALESCE(public.jg_contract_economic_review_ownership_date(NEW::public."OperatingFact"), public.jg_company_repayment_ownership_date(NEW."sourceType", NEW."sourceBusinessId", NEW."projectId"), NEW."occurredAt")::DATE))
    ORDER BY participant."id" FOR SHARE;

  FOREACH candidate_company_id IN ARRAY ARRAY[
    CASE WHEN NEW."debtorSubjectKind" = 'participating_company' THEN NEW."debtorSubjectId" ELSE NULL END,
    CASE WHEN NEW."creditorSubjectKind" = 'participating_company' THEN NEW."creditorSubjectId" ELSE NULL END,
    CASE WHEN NEW."approvedPayerSubjectKind" = 'participating_company' THEN NEW."approvedPayerSubjectId" ELSE NULL END,
    CASE WHEN NEW."actualPayerSubjectKind" = 'participating_company' THEN CASE WHEN NEW."sourceType" = 'payment_execution' AND public."jg_registered_payment_source_matches"(NEW."sourceBusinessId",NEW."projectId",NEW."amountCents",NEW."actualPayerSubjectKind",NEW."actualPayerSubjectId") THEN NULL ELSE NEW."actualPayerSubjectId" END ELSE NULL END,
    CASE WHEN NEW."payeeSubjectKind" = 'participating_company' THEN NEW."payeeSubjectId" ELSE NULL END,
    CASE WHEN NEW."costBearingCompanySubjectKind" = 'participating_company' THEN NEW."costBearingCompanySubjectId" ELSE NULL END
  ]::TEXT[] LOOP
    IF candidate_company_id IS NULL THEN CONTINUE; END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM "ProjectParticipatingCompany" participant
      WHERE participant."projectId" = NEW."projectId"
        AND (
          participant."companyEntityId" = candidate_company_id
          OR participant."companyEntityVersionId" = candidate_company_id
        )
        AND participant."effectiveFrom" <= COALESCE(public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact"), public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END), COALESCE(public.jg_contract_economic_review_ownership_date(NEW::public."OperatingFact"), public.jg_company_repayment_ownership_date(NEW."sourceType", NEW."sourceBusinessId", NEW."projectId"), NEW."occurredAt")::DATE)
        AND (participant."endedAt" IS NULL OR participant."endedAt" > COALESCE(public.jg_contract_review_archive_v2_ownership_day(NEW::public."OperatingFact"), public.jg_contract_archive_v2_ownership_day(CASE WHEN NEW."sourceType" = 'contract_version' THEN NEW."sourceBusinessId" ELSE NULL END), COALESCE(public.jg_contract_economic_review_ownership_date(NEW::public."OperatingFact"), public.jg_company_repayment_ownership_date(NEW."sourceType", NEW."sourceBusinessId", NEW."projectId"), NEW."occurredAt")::DATE))
    ) THEN
      RAISE EXCEPTION '经营事实引用的我方公司未在本项目事实日参与'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;

  IF NEW."adjustsFactId" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "OperatingFact" original
    WHERE original."id" = NEW."adjustsFactId"
      AND original."projectId" = NEW."projectId"
  ) THEN
    RAISE EXCEPTION '更正或冲销只能引用同一项目的经营事实' USING ERRCODE = '23514';
  END IF;
  IF current_setting('app.operating_ledger_actor', true) IS DISTINCT FROM NEW."recordedByUserId" THEN
    RAISE EXCEPTION '正式经营事实必须通过已授权的经营账服务登记' USING ERRCODE = '42501';
  END IF;
  IF NEW."factKind" IN ('owner_settlement', 'downstream_settlement')
     AND (NEW."debtorSubjectKind" IS NULL OR NEW."creditorSubjectKind" IS NULL) THEN
    RAISE EXCEPTION '结算事实必须填写债务主体和债权主体' USING ERRCODE = '23514';
  END IF;
  IF NEW."factKind" IN ('owner_payment', 'downstream_payment', 'fund_movement')
     AND (NEW."actualPayerSubjectKind" IS NULL OR NEW."payeeSubjectKind" IS NULL) THEN
    RAISE EXCEPTION '付款或资金事实必须填写实际付款主体和收款主体' USING ERRCODE = '23514';
  END IF;
  IF NEW."factKind" = 'expense' AND NEW."costBearingCompanySubjectKind" IS NULL THEN
    RAISE EXCEPTION '费用事实必须填写成本承担公司' USING ERRCODE = '23514';
  END IF;
  IF NEW."factKind" = 'employee_loan'
     AND (NEW."debtorSubjectKind" IS NULL OR NEW."creditorSubjectKind" IS NULL) THEN
    RAISE EXCEPTION '员工借款事实必须填写债务主体和债权主体' USING ERRCODE = '23514';
  END IF;
  IF NEW."factKind" = 'project_wage' THEN
    IF NEW."sourceType" = 'wage_statement_version' THEN
      PERFORM jg_validate_canonical_wage_operating_fact(NEW);
    ELSIF NEW."costBearingCompanySubjectKind" IS NULL OR NEW."payeeSubjectKind" IS NULL THEN
      RAISE EXCEPTION '工资事实必须填写成本承担公司和收款主体' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW."factKind" = 'construction_enterprise_deduction'
     AND NEW."costBearingCompanySubjectKind" IS NULL THEN
    RAISE EXCEPTION '施工企业扣费事实必须填写成本承担公司' USING ERRCODE = '23514';
  END IF;
  IF NEW."factKind" = 'invoice' AND NEW."payeeSubjectKind" IS NULL THEN
    RAISE EXCEPTION '发票事实必须填写收款主体' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;

DECLARE
  fact_occurred_at TIMESTAMP(3);
  fact_new_archive_day DATE;
  fact_affiliate_assignment_id TEXT;
  fact_affiliate_version_id TEXT;
  fact_evidence_level TEXT;
  fact_entry_kind TEXT;
  fact_adjusts_fact_id TEXT;
  fact_recorded_by_user_id TEXT;
  fact_source_type TEXT;
  fact_fund_execution_id TEXT;
  original_impact_id TEXT;
  original_impact_kind TEXT;
  original_impact_amount BIGINT;
  original_impact_direction TEXT;
  original_subject_role TEXT;
  original_subject_kind TEXT;
  original_subject_id TEXT;
  original_cost_category_code TEXT;
  original_fund_purpose TEXT;
  original_impact_snapshot JSONB;
  is_fund_execution_reversal BOOLEAN := FALSE;
  reversed_impact_amount BIGINT;
BEGIN
  SELECT COALESCE(public.jg_contract_economic_review_ownership_date(fact), public.jg_company_repayment_ownership_date(fact."sourceType", fact."sourceBusinessId", fact."projectId"), fact."occurredAt"), fact."affiliateAssignmentId",
         fact."affiliateBusinessPartyVersionId", fact."evidenceLevel",
         fact."entryKind", fact."adjustsFactId", fact."recordedByUserId",
         fact."sourceType", fact."fundExecutionId"
    INTO fact_occurred_at, fact_affiliate_assignment_id,
         fact_affiliate_version_id, fact_evidence_level, fact_entry_kind,
         fact_adjusts_fact_id, fact_recorded_by_user_id, fact_source_type,
         fact_fund_execution_id
    FROM "OperatingFact" fact
   WHERE fact."id" = NEW."factId"
     AND fact."projectId" = NEW."projectId"
     AND fact."sourceType" = NEW."sourceType"
     AND fact."sourceBusinessId" = NEW."sourceBusinessId";
  IF fact_occurred_at IS NULL THEN
    RAISE EXCEPTION '影响分录必须引用同一项目、同一来源的经营事实'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(public.jg_contract_review_archive_v2_ownership_day(fact), public.jg_contract_archive_v2_ownership_day(CASE WHEN fact."sourceType"='contract_version' THEN fact."sourceBusinessId" ELSE NULL END)) INTO fact_new_archive_day FROM public."OperatingFact" fact WHERE fact."id"=NEW."factId" AND fact."projectId"=NEW."projectId" AND fact."sourceType"=NEW."sourceType" AND fact."sourceBusinessId"=NEW."sourceBusinessId";
  IF fact_evidence_level = 'C' AND NEW."impactKind" <> 'evidence_gap_notice' THEN
    RAISE EXCEPTION 'C级证据只能登记缺口提示，不能产生正式经营影响'
      USING ERRCODE = '23514';
  END IF;
  IF NEW."subjectKind" IS NOT NULL
     AND NEW."subjectKind" NOT IN (
       'owner', 'construction_enterprise', 'participating_company',
       'downstream_counterparty', 'employee', 'public_cash'
     ) THEN
    RAISE EXCEPTION '当前经营账尚未接入该影响主体种类，不能登记正式分录'
      USING ERRCODE = '23514';
  END IF;
  IF NEW."subjectKind" = 'construction_enterprise' AND NOT EXISTS (
    SELECT 1 FROM "ProjectAffiliateAssignment" assignment
     WHERE assignment."id" = fact_affiliate_assignment_id
       AND assignment."projectId" = NEW."projectId"
       AND assignment."businessPartyVersionId" = fact_affiliate_version_id
       AND (NEW."subjectId" = assignment."businessPartyId"
         OR NEW."subjectId" = assignment."businessPartyVersionId")
       AND assignment."effectiveFrom" <= COALESCE(fact_new_archive_day, fact_occurred_at::DATE)
       AND (assignment."endedAt" IS NULL
         OR assignment."endedAt" > COALESCE(fact_new_archive_day, fact_occurred_at::DATE))
  ) THEN
    RAISE EXCEPTION '影响分录引用的施工企业在事实日无效'
      USING ERRCODE = '23514';
  END IF;
  IF NEW."subjectKind" = 'participating_company' THEN
    PERFORM 1 FROM "Project"
      WHERE "id" = NEW."projectId"
      FOR UPDATE;
    PERFORM participant."id"
      FROM "ProjectParticipatingCompany" participant
      WHERE participant."projectId" = NEW."projectId"
        AND (
          NEW."subjectId" = participant."companyEntityId"
          OR NEW."subjectId" = participant."companyEntityVersionId"
        )
        AND participant."effectiveFrom" <= COALESCE(fact_new_archive_day, fact_occurred_at::DATE)
        AND (participant."endedAt" IS NULL
          OR participant."endedAt" > COALESCE(fact_new_archive_day, fact_occurred_at::DATE))
      ORDER BY participant."id" FOR SHARE;
    IF NOT FOUND AND NOT coalesce(NEW."sourceType" = 'payment_execution' AND NEW."subjectRole" = 'actual_payer' AND public."jg_registered_payment_impact_matches"(NEW."sourceBusinessId",NEW."projectId",NEW."amountCents",NEW."subjectKind",NEW."subjectId",NEW."impactKind",NEW."sourceImpactKey",NEW."direction",NEW."idempotencyKey"),FALSE) THEN
      RAISE EXCEPTION '影响分录引用的我方公司未在本项目事实日参与'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF fact_entry_kind = 'reversal' THEN
    is_fund_execution_reversal := fact_source_type = 'fund_execution'
      AND EXISTS (
        SELECT 1 FROM "FundExecution" execution
         WHERE execution."id" = fact_fund_execution_id
           AND execution."executionKind" = 'reversal'
      );
    SELECT original_impact."id", original_impact."impactKind",
           original_impact."amountCents", original_impact."direction",
           original_impact."subjectRole", original_impact."subjectKind",
           original_impact."subjectId", original_impact."costCategoryCode",
           original_impact."fundPurpose", original_impact."impactSnapshot"
      INTO original_impact_id, original_impact_kind, original_impact_amount,
           original_impact_direction, original_subject_role,
           original_subject_kind, original_subject_id,
           original_cost_category_code, original_fund_purpose,
           original_impact_snapshot
      FROM "OperatingImpactEntry" original_impact
     WHERE original_impact."factId" = fact_adjusts_fact_id
       AND original_impact."sourceImpactKey" = NEW."sourceImpactKey";
    IF NOT FOUND THEN
      RAISE EXCEPTION '冲销必须逐笔引用原经营影响分录'
        USING ERRCODE = '23514';
    END IF;
    IF original_impact_kind <> NEW."impactKind"
       OR (is_fund_execution_reversal
         AND (NEW."amountCents" <= 0 OR NEW."amountCents" > original_impact_amount))
       OR (NOT is_fund_execution_reversal
         AND original_impact_amount <> NEW."amountCents")
       OR ((original_impact_direction = 'increase' AND NEW."direction" <> 'decrease')
         OR (original_impact_direction = 'decrease' AND NEW."direction" <> 'increase')
         OR (original_impact_direction = 'notice' AND NEW."direction" <> 'notice'))
       OR original_subject_role IS DISTINCT FROM NEW."subjectRole"
       OR original_subject_kind IS DISTINCT FROM NEW."subjectKind"
       OR original_subject_id IS DISTINCT FROM NEW."subjectId"
       OR original_cost_category_code IS DISTINCT FROM NEW."costCategoryCode"
       OR original_fund_purpose IS DISTINCT FROM NEW."fundPurpose"
       OR (is_fund_execution_reversal AND (
         NEW."impactSnapshot" ->> 'originalOperatingImpactEntryId'
           IS DISTINCT FROM original_impact_id))
       OR (NOT is_fund_execution_reversal
         AND original_impact_snapshot IS DISTINCT FROM NEW."impactSnapshot") THEN
      RAISE EXCEPTION '冲销分录必须使用原分录身份、容量并登记反向影响'
        USING ERRCODE = '23514';
    END IF;
    IF is_fund_execution_reversal THEN
      SELECT COALESCE(SUM(reverse_impact."amountCents"), 0)
        INTO reversed_impact_amount
        FROM "OperatingFact" reverse_fact
        INNER JOIN "OperatingImpactEntry" reverse_impact
          ON reverse_impact."factId" = reverse_fact."id"
       WHERE reverse_fact."adjustsFactId" = fact_adjusts_fact_id
         AND reverse_fact."entryKind" = 'reversal'
         AND reverse_impact."sourceImpactKey" = NEW."sourceImpactKey";
      IF reversed_impact_amount + NEW."amountCents" > original_impact_amount THEN
        RAISE EXCEPTION '经营影响累计冲销金额超过原分录'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  IF current_setting('app.operating_ledger_actor', true)
       IS DISTINCT FROM fact_recorded_by_user_id THEN
    RAISE EXCEPTION '正式经营影响必须通过已授权的经营账服务登记'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;

BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'registered fund history is append-only'; END IF;
 IF TG_TABLE_NAME = 'RegisteredFundAccount' THEN
   IF TG_OP = 'UPDATE' AND
      (to_jsonb(NEW) - 'writeRevision') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'writeRevision') AND
      NEW."writeRevision" = OLD."writeRevision" + 1 THEN RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME <> 'FundAccountBalanceRegistration' THEN RAISE EXCEPTION 'registered fund identity and source snapshots are immutable'; END IF;
 IF OLD."status" <> 'pending_review' OR NEW."status" NOT IN ('confirmed', 'returned', 'withdrawn') OR
    (to_jsonb(NEW) - ARRAY['status','confirmedByUserId','confirmedAt','reviewNote','closedByUserId','closedAt','closeReason']) IS DISTINCT FROM
    (to_jsonb(OLD) - ARRAY['status','confirmedByUserId','confirmedAt','reviewNote','closedByUserId','closedAt','closeReason']) THEN
   RAISE EXCEPTION 'only pending reconciliation confirmation is allowed';
 END IF;
 IF NEW."status" = 'confirmed' AND (NOT EXISTS (SELECT 1 FROM "FundAccountBalanceRegistration" p WHERE p."id" = NEW."previousRegistrationId" AND p."accountId" = NEW."accountId" AND p."status" = 'confirmed') OR
    EXISTS (SELECT 1 FROM "FundAccountBalanceRegistration" p WHERE p."accountId" = NEW."accountId" AND p."status" = 'confirmed' AND p."version" >= NEW."version")) THEN
   RAISE EXCEPTION 'reconciliation predecessor changed';
 END IF;
 RETURN NEW;
END

